<?php
session_start(); require 'page-guard.php'; require '../config/db_conn.php'; require '../includes/csrf-token.php'; require 'components.php';
$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");
$conn->query("CREATE TABLE IF NOT EXISTS admin_security (ADMIN_USER VARCHAR(50) PRIMARY KEY, SECURITY_QUESTION VARCHAR(255) NOT NULL, SECURITY_ANSWER VARCHAR(255) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");
$securityConfigured=false;$securityQuestion='';$security=$conn->prepare('SELECT SECURITY_QUESTION FROM admin_security WHERE ADMIN_USER=?');$security->bind_param('s',$_SESSION['admin-user']);$security->execute();if($row=$security->get_result()->fetch_assoc()){$securityConfigured=true;$securityQuestion=$row['SECURITY_QUESTION'];}
$sections=$conn->query("SELECT x.SECTION, COUNT(DISTINCT s.ID) students, COUNT(DISTINCT t.TEACHER_ID) teachers FROM (SELECT SECTION FROM sections UNION SELECT DISTINCT SECTION FROM students WHERE SECTION IS NOT NULL AND SECTION<>'' UNION SELECT DISTINCT SECTION FROM teachers) x LEFT JOIN students s ON s.SECTION=x.SECTION LEFT JOIN teachers t ON t.SECTION=x.SECTION GROUP BY x.SECTION ORDER BY x.SECTION");
adminHead('Settings'); adminSidebar('settings','Settings','Manage administrator security and teacher sections'); ?>
<div class="grid gap-7 lg:grid-cols-2"><section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><h2 class="text-xl font-black text-slate-900">Change admin password</h2><form action="settings-save.php" method="post" class="mt-6 space-y-4"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="password"><label class="block text-sm font-bold">Current password<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="current_password" required></label><label class="block text-sm font-bold">New password<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="new_password" minlength="8" required></label><label class="block text-sm font-bold">Confirm new password<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="confirm_password" minlength="8" required></label><button class="w-full rounded-xl bg-blue-600 px-5 py-3 font-bold text-white">Update password</button></form></section><section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><h2 class="text-xl font-black text-slate-900">Password recovery</h2><p class="mt-1 text-sm text-slate-500">Choose a security question used to reset the administrator password.</p><?php if($securityConfigured): ?><p class="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm font-semibold text-emerald-700">Configured: <?= htmlspecialchars($securityQuestion) ?></p><?php endif; ?><form action="settings-save.php" method="post" class="mt-5 space-y-4"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="security_question"><label class="block text-sm font-bold">Current password<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="current_password" required></label><label class="block text-sm font-bold">Security question<select class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3" name="security_question" required><option value="What was the name of your first pet?">What was the name of your first pet?</option><option value="What city were you born in?">What city were you born in?</option><option value="What is your favorite teacher's surname?">What is your favorite teacher's surname?</option></select></label><label class="block text-sm font-bold">Answer<input class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" name="security_answer" autocomplete="off" required></label><button class="w-full rounded-xl bg-slate-900 px-5 py-3 font-bold text-white">Save security question</button></form></section><section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8 lg:col-span-2"><h2 class="text-xl font-black text-slate-900">Teacher sections</h2><p class="mt-1 text-sm text-slate-500">Add, rename, and remove unassigned sections.</p><form action="settings-save.php" method="post" class="mt-5 flex gap-2"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="add_section"><input class="min-w-0 flex-1 rounded-xl border border-slate-300 px-4 py-3" name="section" placeholder="e.g. BSIT-4C" required><button class="rounded-xl bg-slate-900 px-4 py-3 font-bold text-white">Add</button></form><div class="mt-5 max-h-96 divide-y divide-slate-100 overflow-y-auto pr-2"><?php while($section=$sections->fetch_assoc()): ?><form action="settings-save.php" method="post" class="flex flex-wrap items-center gap-2 py-3"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="rename_section"><input type="hidden" name="old_section" value="<?= htmlspecialchars($section['SECTION']) ?>"><input class="min-w-0 flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold" name="section" value="<?= htmlspecialchars($section['SECTION']) ?>"><span class="text-xs text-slate-500"><?= $section['students'] ?> students · <?= $section['teachers'] ?> teachers</span><button class="rounded-lg bg-blue-600 px-3 py-2 text-sm font-bold text-white hover:bg-blue-700">Save</button><button type="button" data-delete-section="<?= htmlspecialchars($section['SECTION']) ?>" class="rounded-lg p-2 text-xl leading-none text-rose-600 hover:bg-rose-50" aria-label="Delete section">&times;</button></form><?php if(!$section['students'] && !$section['teachers']): ?><?php endif; ?><?php endwhile; ?></div></section></div><div id="delete-section-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-slate-950/60 p-5"><div class="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><h3 class="text-xl font-black text-slate-900">Delete section?</h3><p class="mt-2 text-sm text-slate-500">Only sections with no linked students or teachers can be deleted.</p><form action="settings-save.php" method="post" class="mt-6 flex gap-3"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="delete_section"><input id="delete-section-value" type="hidden" name="section"><button type="button" id="cancel-delete-section" class="flex-1 rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button><button class="flex-1 rounded-xl bg-rose-600 px-4 py-3 font-bold text-white">Delete</button></form></div></div><script>const sectionModal=document.getElementById('delete-section-modal'),sectionValue=document.getElementById('delete-section-value');document.querySelectorAll('[data-delete-section]').forEach(button=>button.onclick=()=>{sectionValue.value=button.dataset.deleteSection;sectionModal.classList.replace('hidden','flex')});document.getElementById('cancel-delete-section').onclick=()=>sectionModal.classList.replace('flex','hidden');</script><?php adminFoot(); ?>